/* Lesson 65 solution (optional): a PIO state machine drives four LEDs, and a DMA
 * channel feeds it one word per step. The CPU only starts the DMA and waits.
 *
 * The PIO program is embedded as instruction words. A normal Pico SDK project
 * writes a .pio file and lets pioasm generate this struct (see the lesson). */
// EXPECT: PIO DMA OK
#include <stdio.h>

#include "pico/stdlib.h"
#include "hardware/dma.h"
#include "hardware/pio.h"
#include "pattern.pio.h"   /* generated by pioasm from pattern.pio */

#define PATTERN_PIO        pio0
#define PATTERN_SM         0u
#define PATTERN_BASE_PIN   10u   /* GP10 .. GP13 drive four LEDs */
#define PATTERN_PIN_COUNT  4u

/* PIO clock = 125 MHz / 60000, about 2.08 kHz. One step takes 33 PIO cycles
 * (pull: 1, then out with a delay of 31: 32), so one step is 33 x 0.48 ms = 15.84 ms. */
#define PATTERN_CLKDIV_INT 60000u

/* PIO program, from RP2040 datasheet section 3.4 (Table 366).
 *   0x80A0  pull block            100 00000 1 0 1 00000
 *                                 PULL, no delay, block until the TX FIFO has data
 *   0x7F04  out pins, 4 [31]      011 11111 000 00100
 *                                 OUT, delay 31, destination PINS, bit count 4 */
static const uint16_t hand_decoded_words[] = {
    0x80A0,
    0x7F04,
};

#define HAND_WORD_COUNT (sizeof hand_decoded_words / sizeof hand_decoded_words[0])

/* Four-bit patterns, one per step. Each is the low four bits of a 32-bit word,
 * because OUT takes the least significant bits first (shift right). */
static const uint32_t steps[] = { 0x1, 0x2, 0x4, 0x8, 0x4, 0x2 };
#define STEP_COUNT (sizeof steps / sizeof steps[0])

int main(void) {
    stdio_init_all();

    /* pioasm generated pattern_program from pattern.pio. Compare its words with the
     * ones decoded by hand from the datasheet: they must be identical. */
    bool words_match = pattern_program.length == HAND_WORD_COUNT;
    for (uint i = 0; words_match && i < HAND_WORD_COUNT; i++) {
        words_match = pattern_program.instructions[i] == hand_decoded_words[i];
    }
    printf("PIO WORDS %s\n", words_match ? "MATCH" : "DIFFER");


    /* Load the program and wire the state machine to the four LED pins. */
    uint offset = pio_add_program(PATTERN_PIO, &pattern_program);
    for (uint i = 0; i < PATTERN_PIN_COUNT; i++) {
        pio_gpio_init(PATTERN_PIO, PATTERN_BASE_PIN + i);
    }
    pio_sm_set_consecutive_pindirs(PATTERN_PIO, PATTERN_SM, PATTERN_BASE_PIN, PATTERN_PIN_COUNT, true);

    pio_sm_config c = pio_get_default_sm_config();
    sm_config_set_wrap(&c, offset, offset + pattern_program.length - 1);
    sm_config_set_out_pins(&c, PATTERN_BASE_PIN, PATTERN_PIN_COUNT);
    sm_config_set_out_shift(&c, true, false, 32);     /* shift right, no autopull */
    sm_config_set_clkdiv_int_frac(&c, PATTERN_CLKDIV_INT, 0);
    pio_sm_init(PATTERN_PIO, PATTERN_SM, offset, &c);

    /* DMA: copy one word into the PIO TX FIFO each time the FIFO asks for one.
     * The DREQ (data request) is the pacing signal: the DMA waits while the FIFO is full. */
    int ch = dma_claim_unused_channel(true);
    dma_channel_config dc = dma_channel_get_default_config(ch);
    channel_config_set_transfer_data_size(&dc, DMA_SIZE_32);
    channel_config_set_read_increment(&dc, true);     /* walk through steps[] */
    channel_config_set_write_increment(&dc, false);   /* always the same FIFO register */
    channel_config_set_dreq(&dc, pio_get_dreq(PATTERN_PIO, PATTERN_SM, true));
    dma_channel_configure(ch, &dc, &PATTERN_PIO->txf[PATTERN_SM], steps, STEP_COUNT, false);

    pio_sm_set_enabled(PATTERN_PIO, PATTERN_SM, true);
    dma_channel_transfer_from_buffer_now(ch, steps, STEP_COUNT);
    printf("PIO DMA OK steps=%u\n", (unsigned)STEP_COUNT);

    /* Restart the sequence each time the DMA finishes. The CPU does this, not the PIO. */
    while (true) {
        dma_channel_wait_for_finish_blocking(ch);
        dma_channel_transfer_from_buffer_now(ch, steps, STEP_COUNT);
    }
}
